@Composable
fun AddDoseDialog(
    profiles: List<Profile>,
    medications: List<Medication>,
    initialProfileId: Int?,
    defaultNotifyOnNextDose: Boolean,
    onDismiss: () -> Unit,
    onSubmit: (profileId: Int, medicationId: Int, doseAmount: String, notifyOnNextDose: Boolean) -> Unit,
) {
    var selectedProfile by remember {
        mutableStateOf(profiles.firstOrNull { it.id == initialProfileId } ?: profiles.firstOrNull())
    }
    var selectedMedication by remember { mutableStateOf(medications.firstOrNull()) }
    var doseAmount by remember(selectedMedication) {
        mutableStateOf(selectedMedication?.defaultDose.orEmpty())
    }
    var notifyOnNextDose by remember { mutableStateOf(defaultNotifyOnNextDose) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.log_a_dose)) },
        text = {
            Column(modifier = Modifier.fillMaxWidth()) {
                Text(
                    stringResource(R.string.who_label),
                    style = MaterialTheme.typography.labelLarge,
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState())
                        .padding(top = 4.dp),
                ) {
                    profiles.forEach { profile ->
                        ProfileChip(
                            profile = profile,
                            selected = profile.id == selectedProfile?.id,
                            onClick = { selectedProfile = profile },
                        )
                    }
                }

                Text(
                    stringResource(R.string.medication_label),
                    style = MaterialTheme.typography.labelLarge,
                    modifier = Modifier.padding(top = 16.dp),
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState())
                        .padding(top = 4.dp),
                ) {
                    medications.forEach { medication ->
                        MedicationChip(
                            medication = medication,
                            selected = medication.id == selectedMedication?.id,
                            onClick = { selectedMedication = medication },
                        )
                    }
                }

                OutlinedTextField(
                    value = doseAmount,
                    onValueChange = { doseAmount = it },
                    label = { Text(stringResource(R.string.dose_given_label)) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 16.dp),
                )

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 16.dp),
                ) {
                    Text(stringResource(R.string.notify_on_next_dose), modifier = Modifier.weight(1f))
                    Switch(
                        checked = notifyOnNextDose,
                        onCheckedChange = { notifyOnNextDose = it },
                    )
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val profile = selectedProfile
                    val medication = selectedMedication
                    if (profile != null && medication != null) {
                        onSubmit(profile.id, medication.id, doseAmount, notifyOnNextDose)
                    }
                },
            ) {
                Text(stringResource(R.string.log_dose))
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text(stringResource(R.string.cancel))
            }
        },
    )
}
